/** A fresh nonce is generated by the proxy, never accepted from the browser. */
export function createCspNonce(): string {
  return btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(24))));
}

export function contentSecurityPolicy({
  nonce,
  backendUrl,
  siteUrl,
  development,
}: {
  nonce: string;
  backendUrl: string;
  siteUrl: string;
  development: boolean;
}): string {
  if (!/^[A-Za-z0-9+/]{32}$/.test(nonce)) throw new Error("Invalid CSP nonce");
  const backend = new URL(backendUrl);
  if (!["http:", "https:"].includes(backend.protocol)) throw new Error("Invalid backend protocol");
  const directives = [
    "default-src 'self'",
    `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${development ? " 'unsafe-eval'" : ""}`,
    "script-src-attr 'none'",
    // Existing layout/graph style attributes need inline CSS, never inline JS.
    "style-src 'self' 'unsafe-inline'",
    `connect-src 'self' ${backend.origin}${development ? " ws: wss:" : ""}`,
    "img-src 'self' data: blob:",
    "font-src 'self'",
    "manifest-src 'self'",
    "worker-src 'self'",
    "object-src 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    "frame-src 'none'",
  ];
  if (new URL(siteUrl).protocol === "https:") directives.push("upgrade-insecure-requests");
  return directives.join("; ");
}
